mapper.select:
/** pciSql - selectPiaList - 내부인건비/간접비관리 - 월별 직접비/간접비 목록 조회 */ SELECT VPROJECTCODE as "vProjectCode" , VYEAR as "vYear" , VCLASS as "vClass" , N1MONAMOUNT as "n1MonAmount" , N2MONAMOUNT as "n2MonAmount" , N3MONAMOUNT as "n3MonAmount" , N4MONAMOUNT as "n4MonAmount" , N5MONAMOUNT as "n5MonAmount" , N6MONAMOUNT as "n6MonAmount" , N7MONAMOUNT as "n7MonAmount" , N8MONAMOUNT as "n8MonAmount" , N9MONAMOUNT as "n9MonAmount" , N10MONAMOUNT as "n10MonAmount" , N11MONAMOUNT as "n11MonAmount" , N12MONAMOUNT as "n12MonAmount" FROM TCA4009
VYEAR = #{vYear}
ORDER BY VPROJECTCODE

mapper.insert:
/** pciSql - insertPia - 월별 직접비/간접비 입력(업로드) */
INSERT INTO TCA4009 (
     VPROJECTCODE
   , VYEAR
   , VCLASS
   , N1MONAMOUNT
   , N2MONAMOUNT
   , N3MONAMOUNT
   , N4MONAMOUNT
   , N5MONAMOUNT
   , N6MONAMOUNT
   , N7MONAMOUNT
   , N8MONAMOUNT
   , N9MONAMOUNT
   , N10MONAMOUNT
   , N11MONAMOUNT
   , N12MONAMOUNT
) VALUES
(
     #{vProjectCode}
   , #{vYear}
   , #{vClass}
   , #{n1MonAmount, jdbcType=DOUBLE}
   , #{n2MonAmount, jdbcType=DOUBLE}
   , #{n3MonAmount, jdbcType=DOUBLE}
   , #{n4MonAmount, jdbcType=DOUBLE}
   , #{n5MonAmount, jdbcType=DOUBLE}
   , #{n6MonAmount, jdbcType=DOUBLE}
   , #{n7MonAmount, jdbcType=DOUBLE}
   , #{n8MonAmount, jdbcType=DOUBLE}
   , #{n9MonAmount, jdbcType=DOUBLE}
   , #{n10MonAmount, jdbcType=DOUBLE}
   , #{n11MonAmount, jdbcType=DOUBLE}
   , #{n12MonAmount, jdbcType=DOUBLE}
)

mapper.update:
/** pciSql - updatePia - 월별 직접비/간접비 수정 */ UPDATE TCA4009
N1MONAMOUNT = #{n1MonAmount}, N2MONAMOUNT = #{n2MonAmount}, N3MONAMOUNT = #{n3MonAmount}, N4MONAMOUNT = #{n4MonAmount}, N5MONAMOUNT = #{n5MonAmount}, N6MONAMOUNT = #{n6MonAmount}, N7MONAMOUNT = #{n7MonAmount}, N8MONAMOUNT = #{n8MonAmount}, N9MONAMOUNT = #{n9MonAmount}, N10MONAMOUNT = #{n10MonAmount}, N11MONAMOUNT = #{n11MonAmount}, N12MONAMOUNT = #{n12MonAmount},
VPROJECTCODE = #{vProjectCode} AND VYEAR = #{vYear} AND VCLASS = #{vClass}

mapper.delete:
