DELETE FROM TCA4009

       VPROJECTCODE = #{vProjectCode}
   AND VYEAR = #{vYear}
   AND VCLASS = #{vClass}

mapper.insert:
/** pciSql - insertPiaMonthlyAuto - 월별 내부인건비/간접비 입력(계산) */
{
   CALL SP_BATCH_LABORINDIRECT(#{vYyyy, mode=IN, jdbcType=VARCHAR, javaType=String}, #{vGubun, mode=IN, jdbcType=VARCHAR, javaType=String})
}

mapper.select:
/** pciSql - selectPiaList - 내부인건비/간접비관리 - 직접비/간접비 목록 조회(분기별/반기별) */ SELECT VESTICODE as "vEstiCode" , VPROJECTCODE as "vProjectCode" , NDIRECTAMOUNT as "nDirectAmount" , NINDIRECTAMOUNT as "nIndirectAmount" , NAMOUNT as "nAmount" FROM TCA4012
VESTICODE = #{vEstiCode}
ORDER BY VPROJECTCODE

mapper.insert:
/** pciSql - insertPiaHalfYear - 직접비/간접비 입력(분기별/반기별) */
INSERT INTO TCA4012 (
     VESTICODE
   , VPROJECTCODE
   , NDIRECTAMOUNT
   , NINDIRECTAMOUNT
   , NAMOUNT
) VALUES
(
     #{vEstiCode}
   , #{vProjectCode}
   , #{nDirectAmount  , jdbcType=DOUBLE}
   , #{nIndirectAmount, jdbcType=DOUBLE}
   , #{nAmount        , jdbcType=DOUBLE}
)

/** pciSql - insertPiaHalfYearAuto - 내부인건비/간접비(분기별/반기별) 입력(계산) */ INSERT INTO TCA4012 SELECT #{vEstiCode} , VPROJECTCODE , SUM(NDIRECTAMOUNT) , SUM(NINDIRECTAMOUNT) , SUM(NDIRECTAMOUNT) + SUM(NINDIRECTAMOUNT) FROM (
SELECT VPROJECTCODE , DECODE(VCLASS, '01', N1MONAMOUNT + N2MONAMOUNT + N3MONAMOUNT + N4MONAMOUNT + N5MONAMOUNT + N6MONAMOUNT, 0) NDIRECTAMOUNT , DECODE(VCLASS, '02', N1MONAMOUNT + N2MONAMOUNT + N3MONAMOUNT + N4MONAMOUNT + N5MONAMOUNT + N6MONAMOUNT, 0) NINDIRECTAMOUNT FROM TCA4009 WHERE VYEAR = #{vYyyy}
SELECT VPROJECTCODE , DECODE(VCLASS, '01', N7MONAMOUNT + N8MONAMOUNT + N9MONAMOUNT + N10MONAMOUNT + N11MONAMOUNT + N12MONAMOUNT, 0) NDIRECTAMOUNT , DECODE(VCLASS, '02', N7MONAMOUNT + N8MONAMOUNT + N9MONAMOUNT + N10MONAMOUNT + N11MONAMOUNT + N12MONAMOUNT, 0) NINDIRECTAMOUNT FROM TCA4009 WHERE VYEAR = #{vYyyy}
SELECT VPROJECTCODE , DECODE(VCLASS, '01', N1MONAMOUNT + N2MONAMOUNT + N3MONAMOUNT, 0) NDIRECTAMOUNT , DECODE(VCLASS, '02', N1MONAMOUNT + N2MONAMOUNT + N3MONAMOUNT, 0) NINDIRECTAMOUNT FROM TCA4009 WHERE VYEAR = #{vYyyy}
SELECT VPROJECTCODE , DECODE(VCLASS, '01', N4MONAMOUNT + N5MONAMOUNT + N6MONAMOUNT, 0) NDIRECTAMOUNT , DECODE(VCLASS, '02', N4MONAMOUNT + N5MONAMOUNT + N6MONAMOUNT, 0) NINDIRECTAMOUNT FROM TCA4009 WHERE VYEAR = #{vYyyy}
SELECT VPROJECTCODE , DECODE(VCLASS, '01', N7MONAMOUNT + N8MONAMOUNT + N9MONAMOUNT, 0) NDIRECTAMOUNT , DECODE(VCLASS, '02', N7MONAMOUNT + N8MONAMOUNT + N9MONAMOUNT, 0) NINDIRECTAMOUNT FROM TCA4009 WHERE VYEAR = #{vYyyy}
SELECT VPROJECTCODE , DECODE(VCLASS, '01', N10MONAMOUNT + N11MONAMOUNT + N12MONAMOUNT, 0) NDIRECTAMOUNT , DECODE(VCLASS, '02', N10MONAMOUNT + N11MONAMOUNT + N12MONAMOUNT, 0) NINDIRECTAMOUNT FROM TCA4009 WHERE VYEAR = #{vYyyy}
) GROUP BY VPROJECTCODE

mapper.update:
/** pciSql - updatePiaHalfYear - 직접비/간접비(분기별/반기별) 수정 */
UPDATE TCA4012

    NDIRECTAMOUNT   = #{nDirectAmount}  , 
    NINDIRECTAMOUNT = #{nIndirectAmount}, 
    NAMOUNT         = #{nDirectAmount} + #{nIndirectAmount}, 


       VESTICODE = #{vEstiCode}
   AND VPROJECTCODE = #{vProjectCode}

mapper.delete:
