DELETE FROM TCA4012

       VESTICODE = #{vEstiCode}
 
  
   AND VPROJECTCODE = #{vProjectCode}

/** pciSql - deletePiaAll - 월별 내부인건비/간접비 전체 삭제 */
DELETE FROM TCA4009

   VYEAR = #{vYear}

mapper.select:
/** pciSql - selectPibList - 개인별인건비 - 개인별인건비 조회 */ SELECT A.VESTICODE as "vEstiCode" , A.VEMPLNO as "vEmplNo" , B.VNAME as "vName" , ( SELECT VPOSNAME FROM TAZ2003 WHERE VPOSCODE = B.VPOSCODE AND VUSEYN = 'Y' ) as "vPosName" , ( SELECT VTEAMNAME FROM TAZ2001 WHERE VTEAMCODE = B.VDEPTCODE AND VTEAMFLAG IN ('1', '2') AND VUSEYN = 'Y' ) as "vDeptName" , ( SELECT VTEAMNAME FROM TAZ2001 WHERE VTEAMCODE = B.VTEAMCODE AND VTEAMFLAG = '3' AND VUSEYN = 'Y' ) as "vTeamName" , A.NAMOUNT as "nAmount" FROM TCA4008 A, TAA2101 B
A.VEMPLNO = B.VEMPLNO AND A.VESTICODE = #{vEstiCode}
ORDER BY VNAME

mapper.insert:
/** pciSql - insertPib - 개인별인건비 입력 */
INSERT INTO TCA4008 (
     VESTICODE
   , VEMPLNO
   , NAMOUNT
)
VALUES
(
     #{vEstiCode}
   , #{vEmplNo}
   , #{nAmount, jdbcType=DOUBLE}
)

mapper.update:
/** pciSql - updatePib - 개인별인건비  수정 */
UPDATE TCA4008

    NAMOUNT = #{nAmount} 


       VESTICODE = #{vEstiCode}
   AND VEMPLNO = #{vEmplNo}

mapper.delete:
/** pciSql - deletePib - 개인별인건비 삭제 */
DELETE FROM TCA4008

       VESTICODE = #{vEstiCode}
   AND VEMPLNO = #{vEmplNo}

/** pciSql - deletePibAll - 개인별인건비 전체 삭제 */
DELETE FROM TCA4008

   VESTICODE = #{vEstiCode}

mapper.select:
/** pciSql - selectPicGrid2List - 인건비 확보 - 인건비확보율관리 조회 */ SELECT A.VESTICODE as "vEstiCode" /* 평가코드 */ , A.VPROJECTCODE as "vProjectCode" /* 과제코드 */ , B.VKEYPROJECTNAME as "vProjectName" /* 과제명 */ , A.VEMPLNO as "vEmplNo" /* 사번 */ , C.VNAME as "vName" /* 성명 */ , C.VDEPTCODE as "vDeptCode" /* 부서코드 */ , (SELECT VTEAMNAME FROM TAZ2001 WHERE C.VDEPTCODE = VTEAMCODE AND VUSEYN = 'Y' AND VTEAMFLAG IN ('1', '2')) as "vDeptName" /* 부서명 */ , C.VTEAMCODE as "vTeamCode" /* 팀코드 */ , VTEAMNAME as "vTeamName" /* 팀명 */ , (SELECT VPOSNAME FROM TAZ2003 WHERE C.VPOSCODE = VPOSCODE AND VUSEYN = 'Y') as "vPosName" /* 직위명 */ , A.NCONTRIBUTION as "nContribution" /* 참여율 */ FROM TCA4005 A, TCZ2003 B, TAA2101 C, TAZ2001 D
A.VESTICODE = #{vEstiCode} AND B.VKEYPROJECTCODE = SUBSTR(A.VPROJECTCODE, 1, 5) AND C.VEMPLNO = A.VEMPLNO AND D.VTEAMCODE = C.VTEAMCODE
ORDER BY A.VESTICODE, A.VPROJECTCODE, A.VEMPLNO

/** pciSql - selectPicGrid3List - 인건비 확보 - 인건비확보율관리 조회 */ SELECT A.VEMPLNO as "vEmplNo" /* 사번 */ , B.VNAME as "vName" /* 성명 */ , B.VDEPTCODE as "vDeptCode" /* 부서코드 */ , (SELECT VTEAMNAME FROM TAZ2001 WHERE B.VDEPTCODE = VTEAMCODE AND VUSEYN = 'Y' AND VTEAMFLAG IN ('1', '2')) as "vDeptName" /* 부서명 */ , B.VTEAMCODE as "vTeamCode" /* 팀코드 */ , C.VTEAMNAME as "vTeamName" /* 팀코드명 */ , (SELECT VPOSNAME FROM TAZ2003 WHERE B.VPOSCODE = VPOSCODE AND VUSEYN = 'Y') as "vPosName" /* 직위명 */ , (SELECT COUNT(DISTINCT SUBSTR(VPROJECTCODE, 1, 5)) FROM TCA4005 WHERE A.VEMPLNO = VEMPLNO AND VESTICODE = #{vEstiCode} AND NCONTRIBUTION != 0) as "nProjectCnt" /* 과제건수 */ , (SELECT SUM(NCONTRIBUTION) FROM TCA4005 WHERE A.VEMPLNO = VEMPLNO AND VESTICODE = #{vEstiCode}) as "nContribution" /* 참여율 */ , A.NLABORCOST as "nLaborCost" /* 인건비 */ , D.NAMOUNT as "nAmount" /* 연봉 */ , ROUND(A.NLABORCOST / D.NAMOUNT * 100, 2) as "nSecureRate" /* 확보율 */ FROM (SELECT VESTICODE, VEMPLNO, SUM(NLABORCOST) NLABORCOST FROM TCA4007 WHERE VESTICODE = #{vEstiCode}
AND VEMPLNO = #{vEmplNo}
GROUP BY VESTICODE, VEMPLNO) A, TAA2101 B, TAZ2001 C, TCA4008 D
A.VEMPLNO = B.VEMPLNO AND B.VTEAMCODE = C.VTEAMCODE AND A.VEMPLNO = D.VEMPLNO AND A.VESTICODE = D.VESTICODE

mapper.delete:
/** pciSql - deletePic - 인건비 확보 - 인건비확보율관리 - 인건비확보액 삭제 */
DELETE FROM
   TCA4007

   VESTICODE = #{vEstiCode}

mapper.insert:
/** pciSql - insertPic - 인건비 확보 - 인건비확보율관리 - 인건비확보액  입력(계산) */
INSERT INTO TCA4007
   SELECT
        VESTICODE
      , VPROJECTCODE
      , VEMPLNO
      , ROUND(NVL((NCONTRIBUTION / 100) * #{nAmount, jdbcType=INTEGER}, 0))
   FROM TCA4005

       VESTICODE = #{vEstiCode}
   AND VPROJECTCODE = #{vProjectCode}

mapper.select:
/** pciSql - selectPidList - 반기인건비확보율 조회 */ SELECT * FROM ( SELECT D.VDISPLAYORDER, B.VDEPTCODE as "vDeptCode", C.VTEAMNAME as "vDeptName", B.VTEAMCODE as "vTeamCode", D.VTEAMNAME as "vTeamName", A.VEMPLNO as "vEmplno", B.VNAME as "vName", E.VPOSNAME as "vPosName", A.VESTICODE,
/* 과제건수 */ (SELECT COUNT(DISTINCT SUBSTR(VPROJECTCODE,1,5)) FROM TCA4005 WHERE VEMPLNO = A.VEMPLNO AND VESTICODE = A.VESTICODE /* 기여도 0인 경우 제외 */ AND NCONTRIBUTION <> 0 ) AS NPROJECTCNT,
/* 참여율 */ (SELECT SUM(NCONTRIBUTION) FROM TCA4005 WHERE VEMPLNO = A.VEMPLNO AND VESTICODE = A.VESTICODE ) AS NCONTRIBUTION,
A.NLABORCOST, F.NAMOUNT FROM /* 집계 */ ( SELECT VESTICODE, VEMPLNO, SUM(NLABORCOST) NLABORCOST FROM TCA4007 WHERE VESTICODE IN (#{vEstiCode1}, #{vEstiCode2}) GROUP BY VESTICODE, VEMPLNO ) A, TAA2101 B, TAZ2001 C, TAZ2001 D, TAZ2003 E, TCA4008 F WHERE A.VEMPLNO = B.VEMPLNO AND B.VDEPTCODE = C.VTEAMCODE(+) AND B.VTEAMCODE = D.VTEAMCODE(+) AND B.VPOSCODE = E.VPOSCODE AND A.VEMPLNO = F.VEMPLNO AND A.VESTICODE = F.VESTICODE
) PIVOT ( MAX(NPROJECTCNT) AS "nProjectCnt", MAX(NCONTRIBUTION) AS "nContribution", MAX(NLABORCOST) AS "nLaborCost", MAX(NAMOUNT) AS "nAmount" FOR VESTICODE IN ( '${vEstiCode1}' AS E1, '${vEstiCode2}' AS E2 ) ) ORDER BY VDISPLAYORDER ASC

/** pciSql - selectPieList - 연간인건비확보율 조회 */ SELECT * FROM ( SELECT D.VDISPLAYORDER, B.VDEPTCODE AS "vDeptCode", C.VTEAMNAME AS "vDeptName", B.VTEAMCODE AS "vTeamCode", D.VTEAMNAME AS "vTeamName", B.VEMPLNO AS "vEmplno", B.VNAME AS "vName", E.VPOSNAME AS "vPosName", X.HALF, X.NPROJECTCNT, X.NCONTRIBUTION, X.NLABORCOST, X.NAMOUNT FROM ( SELECT VEMPLNO, HALF, SUM(NLABORCOST) AS NLABORCOST, SUM(NAMOUNT) AS NAMOUNT, SUM(NPROJECTCNT) AS NPROJECTCNT, SUM(NCONTRIBUTION) AS NCONTRIBUTION FROM ( /* TCA4007: 인건비 확보액 */ SELECT A.VEMPLNO, CASE WHEN A.VESTICODE IN ('${vYear}-01', '${vYear}-02') THEN 'E1' WHEN A.VESTICODE IN ('${vYear}-03', '${vYear}-04') THEN 'E2' END AS HALF, A.NLABORCOST AS NLABORCOST, 0 AS NAMOUNT, 0 AS NPROJECTCNT, 0 AS NCONTRIBUTION FROM TCA4007 A WHERE A.VESTICODE IN ('${vYear}-01', '${vYear}-02', '${vYear}-03', '${vYear}-04')
UNION ALL
/* TCA4008: 개인별 인건비 */ SELECT F.VEMPLNO, CASE WHEN F.VESTICODE IN ('${vYear}-01', '${vYear}-02') THEN 'E1' WHEN F.VESTICODE IN ('${vYear}-03', '${vYear}-04') THEN 'E2' END AS HALF, 0 AS NLABORCOST, F.NAMOUNT AS NAMOUNT, 0 AS NPROJECTCNT, 0 AS NCONTRIBUTION FROM TCA4008 F WHERE F.VESTICODE IN ('${vYear}-01', '${vYear}-02', '${vYear}-03', '${vYear}-04')
UNION ALL
/* 4005: 과제건수/기여율(반기 합계) - 0 제외 */ SELECT P.VEMPLNO, CASE WHEN P.VESTICODE IN ('${vYear}-01', '${vYear}-02') THEN 'E1' WHEN P.VESTICODE IN ('${vYear}-03', '${vYear}-04') THEN 'E2' END AS HALF, 0 AS NLABORCOST, 0 AS NAMOUNT, COUNT(DISTINCT SUBSTR(P.VPROJECTCODE,1,5)) AS NPROJECTCNT, SUM(P.NCONTRIBUTION) AS NCONTRIBUTION FROM TCA4005 P WHERE P.VESTICODE IN ('${vYear}-01', '${vYear}-02', '${vYear}-03', '${vYear}-04') AND P.NCONTRIBUTION <> 0 GROUP BY P.VEMPLNO, CASE WHEN P.VESTICODE IN ('${vYear}-01', '${vYear}-02') THEN 'E1' WHEN P.VESTICODE IN ('${vYear}-03', '${vYear}-04') THEN 'E2' END ) GROUP BY VEMPLNO, HALF ) X, TAA2101 B, TAZ2001 C, TAZ2001 D, TAZ2003 E WHERE X.VEMPLNO = B.VEMPLNO AND B.VDEPTCODE = C.VTEAMCODE(+) AND B.VTEAMCODE = D.VTEAMCODE(+) AND B.VPOSCODE = E.VPOSCODE AND X.HALF IN ('E1','E2')
/* 기여도 0인 경우 제외 */ AND EXISTS ( SELECT 1 FROM TCA4005 P2 WHERE P2.VEMPLNO = X.VEMPLNO AND P2.VESTICODE IN ('${vYear}-01', '${vYear}-02', '${vYear}-03', '${vYear}-04') AND P2.NCONTRIBUTION <> 0 AND ( (X.HALF = 'E1' AND P2.VESTICODE IN ('${vYear}-01', '${vYear}-02')) OR (X.HALF = 'E2' AND P2.VESTICODE IN ('${vYear}-03', '${vYear}-04')) ) ) ) PIVOT ( MAX(NPROJECTCNT) AS "nProjectCnt", MAX(NCONTRIBUTION) AS "nContribution", MAX(NLABORCOST) AS "nLaborCost", MAX(NAMOUNT) AS "nAmount" FOR HALF IN ('E1' AS E1, 'E2' AS E2) ) ORDER BY VDISPLAYORDER

mapper.update:
/** pciSql - updateEntrust - 내부위탁과제 인건비 업데이트 */
UPDATE TCA4012

   NDIRECTAMOUNT = NDIRECTAMOUNT * 1.3,
   NAMOUNT = (NDIRECTAMOUNT * 1.3) + NINDIRECTAMOUNT


       VESTICODE = #{vEstiCode}
   AND VPROJECTCODE IN
   
      #{projectCode}
